    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Refined sliver avoidance: dynamically adjust penalty based on remaining stream length.
    if post_residual > 0 && post_residual < 24 {
        score += 115.0 * (1.35 - (progress * 0.4));
    }

    // Reward perfect fits and high-value alignment.
    if post_residual == 0 {
        score -= 145.0;
    } else if post_residual % 20 == 0 {
        score -= 32.0;
    }

    // Lookahead: Enhanced lookahead logic for tighter packing.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 130.0;
            let secondary_residual = post_residual - next_item_size;
            if secondary_residual == 0 {
                score -= 70.0;
            } else if secondary_residual >= 25 {
                score -= 42.0;
            } else if secondary_residual < 12 {
                score += 85.0;
            }
        }
    }

    // New Bin Logic: Optimized gatekeeping with non-linear density control.
    if bin_residual == bin_capacity {
        let density_penalty = (open_bins_count as f64).ln() * 35.0;
        score += 95.0 + density_penalty;
        if mean_residual > 15.0 {
            score += 75.0;
        }
    } else {
        let utilization = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        if utilization > 0.55 {
            score -= 65.0 * utilization;
        }

        // If only one bin fits, prioritize it, but strongly penalize creating a sliver.
        if fitting_bins_count == 1 {
            if post_residual < 16 {
                score += 120.0;
            } else {
                score -= 130.0;
            }
        }
    }

    // Global optimization: Dynamic phase-shifting.
    if progress > 0.85 {
        // Aggressively minimize remaining capacity in the final stages.
        score += (post_residual as f64).powf(1.25) * 8.0;
    } else {
        // Use a weighted variance penalty to balance filling efficiency vs flexibility.
        // Penalty is tighter to force better mean convergence.
        score += (post_residual as f64 - mean_residual).abs() * 0.55 * (1.0 - progress);
    }

    // Final sanity check: favor smaller residuals more aggressively when bin count is high
    if open_bins_count > 50 {
        score += (post_residual as f64) * 0.15;
    }

    score
}

