pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating a 'dead zone' (residual too small to fit common items, but too large to be efficient)
    // We penalize residuals in the 1-9 range heavily as they are usually wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // Lookahead logic: if the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // Global state awareness: if we are early in the stream, be more conservative (avoid new bins).
    // If late in the stream, prioritize packing tightly to finish.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // Heavily penalize opening a new bin unless the existing bins are poorly suited.
        let openness_penalty = 25.0 * (1.0 - progress);
        let congestion_reward = (open_bins_count as f64) * 0.5;
        score += 20.0 + openness_penalty - congestion_reward;
    } else {
        // If this is the only bin that fits the item, make it highly attractive.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // Reward bins that keep the residual close to the global mean (balancing).
        let diff_from_mean = (post_residual as f64 - mean_residual).abs();
        score += diff_from_mean * 0.2;
    }

    score
}

