    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (smaller post_residual)
    let mut score = post_res;

    // Penalty for creating "dead space": if post_residual is in the 1-9 range, 
    // it is highly likely to become unusable for future items (min size 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_res / 10.0));
