    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 * (1.0 - (post_res - next_item_size as f64) / bin_capacity as f64);
    }

    // Adaptive thresholding: as we reach the end of the stream, 
    // become more aggressive in filling bins to avoid leaving empty space.
    let fill_urgency = progress * 20.0;
    score += (mean_residual - post_res) * fill_urgency;

    // Discourage opening new bins unless the fit is very poor or we are near the end.
    // If bin_residual == bin_capacity, this is a new bin candidate.
    if bin_residual == bin_capacity {
        // High base cost for opening a new bin, which decreases as the stream progresses.
        score += 35.0 * (1.0 - progress) + (open_bins_count as f64 * 0.5);
    } else {
        // Reward bins that have few alternatives (fitting_bins_count is low).
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
