pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (fragmentation) non-linearly.
    // The "Best Fit" behavior is promoted by rewarding small post_residuals, 
    // but we add a cubic penalty for residuals that are too small to fit common items (e.g., < 10).
    let fragmentation_penalty = if post < 10.0 && post > 0.0 {
        (10.0 - post).powi(3)
    } else {
        0.0
    };

    // Incorporate lookahead: reward bins that leave enough space for the next item
    // if the next item is large.
    let lookahead_penalty = if next_item_size > post_residual && post_residual > 0 {
        (next_item_size - post_residual) as f64 * 2.5
    } else {
        0.0
    };

    // Dynamic thresholding: as the stream progresses, we become more conservative
    // about opening new bins. 
    let new_bin_bias = if bin_residual == bin_capacity {
        // Penalty for opening a new bin increases as we approach the end of the stream,
        // unless we are forced to (handled by the caller's logic).
        25.0 + (progress * 50.0) 
    } else {
        0.0
    };

    // Encourage filling bins that are already closer to the mean residual to maintain
    // consistency across bins (load balancing).
    let balance_factor = (post - mean_residual).abs() * 0.5;

    // Combine factors:
    // We want the lowest score, so we reward low post_residual (Best Fit),
    // but penalize the "danger zone" of tiny unusable slices.
    let mut score = post + fragmentation_penalty + lookahead_penalty + new_bin_bias + balance_factor;

    // If this is the only fitting bin, we reduce the score to ensure we don't 
    // unnecessarily open a new bin unless the new bin bias is extremely high.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}
